package com.gentics.mesh.portal.api.cache;

import java.util.function.Function;

import io.reactivex.Single;
import io.vertx.ext.web.RoutingContext;

/**
 * A common interface for caches provided by the {@link CacheProvider}.
 *
 * <p>
 * Currently only <code>Caffeine</code> based caches are implemented.
 * </p>
 *
 * @param <T> The type of cached objects
 */
public interface PortalCache<T> {

	/**
	 * Remove all entries from the cache.
	 */
	void clear();

	/**
	 * Puth the given <code>value</code> in the cache, using the routing context to create a cache key.
	 *
	 * @param rc The current routing context
	 * @param value The value to cache
	 */
	void put(RoutingContext rc, T value);

	/**
	 * Try to retrieve a value from the cache, using the routing context to create a cache key.
	 *
	 * @param rc The current routing context
	 * @return The cached value matching the key generated from <code>rc</code>, or <code>null</code> if
	 * 		no such value is stored in the cache
	 */
	T getIfPresent(RoutingContext rc);

	/**
	 * Retrieve a value from the cache, or generate it with the given <code>supplier</code>.
	 *
	 * <p>
	 * The routing context is used to generate a cache key.
	 * </p>
	 *
	 * <p>
	 * When subscribed to the returned single, the retrieved value is also put in the cache.
	 * </p>
	 *
	 * @param rc The current routing context
	 * @param supplier A function generating the desired value, if it is not already in the cache.
	 * @return A <code>Single</code> containing the value from the cache or generated by the <code>supplier</code>
	 */
	Single<T> get(RoutingContext rc, Function<RoutingContext, Single<T>> supplier);

	/**
	 * Retrieve a value from the cache, or generate it with the given <code>supplier</code>.
	 *
	 * <p>
	 * The routing context is used to generate a cache key.
	 * </p>
	 *
	 * @param key The cache key
	 * @param supplier A function generating the desired value, if it is not already in the cache.
	 * @return The value from the cache or generated by the <code>supplier</code>
	 */
	T get(String key, Function<String, T> supplier);

	/**
	 * Check whether the cache is potentially blocking (e.g. is disk backed)
	 * 
	 * @return
	 */
	boolean isBlockingCache();
}
